        break L680
      peqin[92, i] = peqel[2, i - ioffn[92]]
    block L685:
      # TRIPLET                          ELOSS=31.80 EV
      if en <= ein[93]: break L685
      block L684:
        block L683:
          if en > xtrp6[ntrp6]: break L683
          block L682:
            fdo j, 2, ntrp6:
              if en <= xtrp6[j]: break L682
            j = ntrp6
          y1 = ln(ytrp6[j])
          y2 = ln(ytrp6[j - 1])
          x1 = ln(xtrp6[j])
          x2 = ln(xtrp6[j - 1])
          a = (y1 - y2) / (x1 - x2)
          b = (x2 * y1 - x1 * y2) / (x2 - x1)
          qin[93, i] = exp(a * ln(en) + b) * 1e-16 * amptrp6
          break L684
        # SCALE BY 1/E**2 ABOVE XTRP6(NTRP6) EV
        qin[93, i] = ytrp6[ntrp6] * pow2(xtrp6[ntrp6] / en) * 1e-16 * amptrp6
      if en <= 2.0 * ein[93]: break L685
      peqin[93, i] = peqel[2, i - ioffn[93]]
    # LOAD BREMSSTRAHLUNG X-SECTIONS
    qin[94, i] = 0.0
    qin[95, i] = 0.0
    qin[96, i] = 0.0
    if not (en <= 1000.0):
      block L710:
        fdo j, 2, nbrem:
          if en <= ebrm[j]: break L710
        j = nbrem
      a = (ln(z1t[j]) - ln(z1t[j - 1])) / (ebrm[j] - ebrm[j - 1])
      b = (ln(z1t[j]) * ebrm[j - 1] - ln(z1t[j - 1]) * ebrm[j]) / (ebrm[j - 1] - ebrm[j])
      a1 = (ln(z6t[j]) - ln(z6t[j - 1])) / (ebrm[j] - ebrm[j - 1])
      b1 = (ln(z6t[j]) * ebrm[j - 1] - ln(z6t[j - 1]) * ebrm[j]) / (ebrm[j - 1] - ebrm[j])
      a2 = (ln(z8t[j]) - ln(z8t[j - 1])) / (ebrm[j] - ebrm[j - 1])
      b2 = (ln(z8t[j]) * ebrm[j - 1] - ln(z8t[j - 1]) * ebrm[j]) / (ebrm[j - 1] - ebrm[j])
      qin[94, i] = exp(a * en + b) * 8.0 * 1e-24
      qin[95, i] = exp(a1 * en + b1) * 3.0 * 1e-24
      qin[96, i] = exp(a2 * en + b2) * 1e-24
    # CALCULATE XSEC SUMS
    # ROTATIONAL SUMS
    # SUMR=0.0
    # SUMMTR=0.0
    # SUMSUPR=0.0
    # SUMSUPMTR=0.0
    # DO 800 K=1,26
    # SUMSUPMTR=SUMSUPMTR+XSECDUM(K)
    # 800 SUMSUPR=SUMSUPR+QIN(K,I)
    # DO 801 K=27,52
    # SUMMTR=SUMMTR+XSECDUM(K)
    # 801 SUMR=SUMR+QIN(K,I)
    # VIBRATION SUMS
    # SUMVIB=0.0
    # DO 810 K=53,56
    # 810 SUMVIB=SUMVIB+QIN(K,I)
    # ATTACHMENT SUM
    # SUMATT=0.0
    # DO 820 K=1,3
    # 820 SUMATT=SUMATT+QATT(K,I)
    # IONISATION SUM
    # SUMION=0.0
    # DO 830 K=1,NION
    # 830 SUMION=SUMION+QION(K,I)
    # SUMIONG=SUMION+QION(27,I)
    # write(6,888) EN,SUMION,SUMIONG
    # 888 FORMAT(' EN=',D13.5,' SUMIONC=',D13.5,' SUMIONG=',D13.5)
    # SUMINEL=SUMR+SUMSUPR+SUMVIB+SUMATT+SUMION
    # WRITE(6,888) EN,SUMSUPR,SUMSUPMTR,SUMR,SUMMTR
    # 888 FORMAT(' EN=',D12.5,' SUPROT=',D12.4,' SUPMTR=',D12.4,'SUMROT=',
    # /D12.4,' MTROT=',D12.4)
    # AINELMT=SUMSUPMTR+SUMMTR
    # QMTSUM=Q(2,I)+AINELMT
    # WRITE(6,889) QMTSUM,AINELMT,Q(2,I)
    # 889 FORMAT(' QMTSUM=',D12.4,' AINELMT=',D12.4,' Q(2,I)=',D12.4)
    # WRITE(6,889) EN,SUMVIB,SUMATT,SUMION
    # 889 FORMAT(' EN=',D12.5,' SUMVIB=',D12.4,' SUMATT=',D12.4,' SUMION=',
    # /D12.4)
    # SUMEXC=0.0
    # DO 850 J=57,82
    # 850 SUMEXC=SUMEXC+QIN(J,I)
    # WRITE(6,901) EN,SUMEXC
    # 901 FORMAT(' EN=',D12.4,' SUMEXC=',D12.4)
    # TOTAL
    # Q(1,I)=Q(2,I)+SUMINEL
  block L1001:
    # IF(NANISO.EQ.0) THEN
    # SET NON ROTATIONAL X-SECTIONS TO ISOTROPIC
